import axios from 'axios';

const getApiUrl = () => {
  const { apiUrl } = window['runConfig'] || {
    apiUrl: 'https://access.stage.redhat.com/subscriptions/link/api/',
  };
  return apiUrl;
};

const makeApiRequest = async (auth, method, url, params = {}, signal) => {
  const token = await auth.getToken();
  return axios({
    method: method,
    url: url,
    headers: { Authorization: `Bearer ${token}` },
    params: params,
    withCredentials: true,
    signal: signal,
  });
};

const getPartnerOrderDetailsAsync = (auth, partnerId, signal) => {
  const url = getApiUrl() + `${partnerId}/details`;
  console.debug('vendorApiUrl : ', url);
  return makeApiRequest(auth, 'get', url, {}, signal);
};

const getVendorOrderDetailsAsync = (auth, partnerId, linkToken, signal) => {
  const url = getApiUrl() + `vendor/${partnerId}/order/${linkToken}`;
  console.debug('vendorApiUrl : ', url);
  return makeApiRequest(auth, 'get', url, {}, signal);
};

const linkPartnerOrderToAccountAsync = (auth, partnerId, termsPdfId) => {
  const url = getApiUrl() + `${partnerId}/link`;
  console.debug(`Linking partner=${partnerId}, terms=${termsPdfId}`);
  return makeApiRequest(auth, 'post', url, { termsPdfId: termsPdfId, linkAllOrders: true }).then((res) => res?.data?.linkSuccessful);
};

const linkVendorOrderToAccountAsync = (auth, partnerId, linkToken, termsPdfId) => {
  const url = getApiUrl() + `vendor/${partnerId}/link`;
  console.debug(`Linking Vendor partnerId=${partnerId}, linkToken=${linkToken}, termsPdfId=${termsPdfId}, endpoint=${url}`);
  return makeApiRequest(auth, 'post', url, { linkToken: linkToken, termsPdfId: termsPdfId }).then((res) => res?.data?.linkSuccessful);
};

export { getPartnerOrderDetailsAsync, getVendorOrderDetailsAsync, linkPartnerOrderToAccountAsync, linkVendorOrderToAccountAsync };