import PropTypes from 'prop-types';
import React, { useState } from 'react';
import ReviewLinkAccount from '../review-link/review-link-account';
import ReviewLinkOrder from '../review-link/vendor/review-link-order';
import { Route, Routes, useLocation, useParams } from 'react-router-dom';
import ErrorNotification from '../stratosphere-notifications/error-notification';
import getStratosphereErrorPaths from '../stratosphere-error-paths/get-stratosphere-error-paths';
import { useTranslation } from 'react-i18next';
// import { stringifyJson } from '../shared/utils';
const StratosphereApp = ({ useToast, local }) => {
  const { t, i18n } = useTranslation();
  const { partnerId } = useParams();

  const getDecodedData = () => {
    const encodedData = new URLSearchParams(useLocation().search).get('data');
    const decodedData = encodedData ? JSON.parse(decodeURIComponent(encodedData)) : {};
    console.debug('getDecodedData : ', decodedData, ' Partnerid : ', partnerId);
    return decodedData;
  };

  const localWithPartner = (key, options) =>
    local(key, {
      ...options,
      ns: partnerId,
    });
  const errorPaths = getStratosphereErrorPaths(partnerId);

  return (
    <Routes>
      <Route path="vendor/:partnerId/:linkToken" element={<ReviewLinkOrder local={localWithPartner} useToast={useToast} />} />
      <Route path=":partnerId" element={<ReviewLinkAccount local={localWithPartner} useToast={useToast} />} />

      <Route path=":partnerId/system-error" element={<ErrorNotification local={t} i18n={i18n} type="general-error" />} />

      {/*<Route path={errorPaths.tokenError()} element={<ErrorNotification local={localWithPartner} type="token-error" />} />*/}
      {/*<Route path={errorPaths.exportError()} element={<ErrorNotification local={localWithPartner} type="export-error" />} />*/}
      {/*<Route path={errorPaths.error()} element={<ErrorNotification local={localWithPartner} type="general-error" />} />*/}
      {/*<Route path={errorPaths.orderError()} element={<ErrorNotification local={localWithPartner} type="general-error" />} />*/}
      {/*<Route path={errorPaths.systemError()} element={<ErrorNotification local={localWithPartner} type="general-error" />} />*/}
      {/*<Route path={errorPaths.needAssistance()} element={<ErrorNotification local={localWithPartner} type="need-assistance" />} />*/}
      {/*<Route path={errorPaths.alreadyLinked() + "/*"} element={<ErrorNotification accountDetails={getDecodedData()} local={localWithPartner} type="already-linked" />} />*/}
    </Routes>
  );
};

StratosphereApp.propTypes = {
  useToast: PropTypes.func.isRequired,
  local: PropTypes.func.isRequired,
};

export default StratosphereApp;
